#pragma once

// What the printer conversation is allowed to know and do about printers.
//
// A printer is app-level, not project-level, so this follows Home rather than
// the workspace contract: the surface owns a narrow interface, and one Orca
// implementation behind it calls the existing owners -- PrinterCatalog,
// PrinterDiscovery, Printers::, SetupCommands::. GUI-free and
// Orca-free so the conversation can be tested without either.

#include "PrinterSetupTypes.hpp"

#include <chrono>
#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::PrinterSetup {

// One spool as a connected printer reports it.
struct PrinterSpool
{
    std::string name;
    std::string material;
    std::string colour; // "#RRGGBB", empty when unknown
};

// A printer already saved in this app: an Orca user printer profile, with the
// facts it was set up with.
struct SavedPrinter
{
    std::string               name;
    std::string               device_id;
    std::string               model;        // display model name
    std::string               model_id;     // profile model id
    std::string               vendor_id;
    std::string               picture;      // cover image path, may be empty
    double                    nozzle{0.};
    std::vector<double>       nozzles;      // sizes this model ships
    std::string               plate;        // untranslated plate name
    std::string               ams;          // "AMS lite", "AMS", or empty
    std::vector<PrinterSpool> spools;
    std::string               activity;     // offline, idle, printing, or empty
    bool                      connected{false};
    // One of OrcaSlicer's own printer profiles, selected in the project, not
    // a printer the person saved: nothing is saved on it, and a change to its
    // settings is saved as a copy under `copy_name`, which is then theirs.
    bool                      stock{false};
    std::string               copy_name;
};

// What the packaged profiles offer, one entry per model.
struct CatalogPrinter
{
    std::string         id; // catalogue id, stable for this session
    std::string         vendor_id;
    std::string         vendor_name;  // the brand, as its vendor file names it
    std::string         model_id;     // the profile's own name, which Orca installs by
    std::string         model_name;   // that name with the brand not repeated
    std::string         device_model_id;
    std::string         build_volume; // "180 × 180 × 180 mm"
    std::string         picture;
    std::string         default_plate; // empty: the profile names none
    std::vector<double> nozzles;
    // The machine profile's own default filament for each nozzle size, in
    // the order of `nozzles`; empty where that profile names none.
    std::vector<std::string> filaments;

    std::string display_name() const { return vendor_name + " " + model_name; }
    std::string filament_for(double nozzle) const
    {
        for (std::size_t i = 0; i < nozzles.size() && i < filaments.size(); ++i)
            if (nozzles[i] == nozzle)
                return filaments[i];
        return {};
    }
};

// Everything the app needs to save a printer the person has just agreed to.
struct AddPrinterRequest
{
    std::string vendor_id;
    std::string model_id;
    std::string variant;  // nozzle size as the profile spells it, e.g. "0.4"
    std::string material; // default filament preset, may be empty
    std::string name;     // display name; empty uses the model name
    std::string device_id;    // a discovered printer's id, when this is one
    // The plate to start projects on, as OrcaSlicer's BedType value; absent
    // leaves the plate OrcaSlicer picks for the profile.
    std::optional<int> plate;
};

// One build plate OrcaSlicer offers for a printer: its BedType value and the
// name OrcaSlicer shows for it.
struct PlateOption
{
    int         type{0};
    std::string label;
};

// One filament preset the printer form offers.
struct FilamentOption
{
    std::string name;     // the preset's name, which installs and selects it
    std::string label;    // the name OrcaSlicer shows in its lists (the alias)
    std::string vendor;   // filament_vendor, e.g. "Generic", "eSUN"
    std::string material; // filament_type, e.g. "PLA"
    // Empty when OrcaSlicer counts it as fitting the printer; otherwise the
    // printers its profile names, as a phrase: "the Prusa CORE One and
    // Prusa XL", or "other printers" when it names none it can say.
    std::string made_for;
    // A person's own preset: the preset it was saved from, when it was.
    std::string base;
};

// What the printer form offers for one model and nozzle, read from the
// packaged profiles as OrcaSlicer would load them. Nothing in it is
// installed until the person finishes the form.
struct SetupOptions
{
    std::string catalog_id;
    double      nozzle{0.};
    // Empty when OrcaSlicer offers no plate choice for this printer.
    std::vector<PlateOption> plates;
    int                      default_plate{0}; // the plate OrcaSlicer starts it on
    std::vector<FilamentOption> filaments;      // compatible, by label
    // The chosen brand's and OrcaSlicer's library filaments that do not fit
    // this printer, by label; picking one saves a copy for the printer.
    std::vector<FilamentOption> others;
    // The person's own filament presets, by name; `made_for` says which do
    // not fit, and picking one of those saves a copy for the printer.
    std::vector<FilamentOption> own;
    std::vector<std::string>    suggested;      // the model's default_materials that are compatible
    std::string                 default_filament; // the profile's own default; may be empty
    // Set when the profiles could not be read; nothing else is then.
    std::string error;
};

// A correction to a printer that already exists. Every field is optional;
// what is left out stays as it is.
struct ChangePrinterRequest
{
    std::string                  name; // the saved printer to change
    std::optional<double>        nozzle;
};

struct ConnectionCandidate
{
    std::string id;
    std::string name;
    std::string address;
    bool lan_mode{false};
    // On the person's Bambu account, and not announced on this network since
    // the app started: where it is, and which mode it is in, are not known.
    bool account_only{false};
};

// How long a connection attempt waits for the printer before it is reported
// as failed. The model is told the same number when an attempt starts.
inline constexpr std::chrono::seconds kConnectionWait{30};

struct PrinterConnectionInfo
{
    std::string provider{"unavailable"};
    std::string state{"not_configured"};
    std::string message;
    std::string device_id;
    std::vector<ConnectionCandidate> candidates;
    std::string address;
    std::string host_type;
    bool signed_in{false};
    bool nozzle_mismatch{false};
    // A Bambu Lab printer, on a computer where Bambu's network plug-in is not
    // installed or not turned on: nothing reaches the printer until it is.
    bool needs_network_plugin{false};
};

// Who holds the UDP port Bambu Lab printers announce themselves on. Discovery
// reports success even when another program holds it, and hears nothing. The
// plug-in takes the port only as the app starts: once it has missed it, neither
// stopping and starting discovery nor reloading the plug-in takes it up.
enum class DiscoveryPort { Ours, Taken, Free };

struct ManualPrinterResult
{
    bool applied{false};
    std::vector<SavedPrinter> added;
};

class IPrinterBackend
{
public:
    virtual ~IPrinterBackend() = default;

    // Reads. The catalogue is every model a person can add from this panel,
    // in a stable order.
    virtual const std::vector<CatalogPrinter>& catalog() const = 0;
    virtual std::vector<DiscoveredPrinter> network_printers() const = 0;
    // Every Bambu Lab printer the app has found and could set up, including
    // one it holds no access code for yet. network_printers() leaves those out.
    virtual std::vector<DiscoveredPrinter> nearby_printers() const { return network_printers(); }
    // The plates and filaments the printer form offers for one catalogue
    // model and nozzle. Called off the GUI thread: it reads files, and what
    // prepare_setup_options took of the person's own presets.
    virtual SetupOptions setup_options(const std::string& catalog_id, double nozzle) const = 0;
    // Takes what setup_options needs of the app's state, on the GUI thread,
    // before any setup_options call it is for.
    virtual void prepare_setup_options() {}
    // Puts `filament` in slot 1 of the printer just added and selected. With
    // `copy`, first saves a copy of it for that printer, which OrcaSlicer
    // keeps in the slot across printer changes; `used` names the preset now
    // in the slot. Returns a message for the person when it could not.
    virtual std::string start_with_filament(const std::string& printer, const std::string& filament, bool copy, std::string& used)
    {
        return "Choosing a filament is unavailable.";
    }
    // Opens OrcaSlicer's Create filament window for the printer just added
    // and selected, and puts a preset made there for it in slot 1. Returns
    // that preset's name, or an empty one when none was made for it.
    virtual std::string create_filament_preset(const std::string& printer) { return {}; }
    virtual std::vector<SavedPrinter>     saved_printers() const = 0;
    // A printer profile OrcaSlicer ships, by its preset name, as a person
    // could pick it; `stock` is set. An empty name when there is none.
    virtual SavedPrinter                  stock_printer(const std::string& name) const = 0;

    // Writes. Each returns an empty string on success, or a message written
    // for the person explaining what stopped it. A change lists the keys of
    // the unsaved edits it dropped from the project's copy in `discarded`.
    virtual std::string add_printer(const AddPrinterRequest& request, SavedPrinter& added) = 0;
    virtual std::string change_printer(const ChangePrinterRequest& request, SavedPrinter& changed,
                                       std::vector<std::string>& discarded) = 0;
    // Deletes a saved printer the way Home's "Remove printer…" does.
    virtual std::string remove_printer(const std::string& name) = 0;

    // The ways to OrcaSlicer's own screens: its printer wizard for a new
    // printer (only where the printer form cannot be shown), its printer
    // settings for an existing one.
    virtual ManualPrinterResult run_manual_setup() = 0;
    virtual void open_printer_settings(const std::string& name) = 0;

    // Connection is a separate operation against an existing saved printer.
    // Credentials are input-only and never part of a snapshot or conversation.
    // connect_printer and connect_host start an attempt and return at once;
    // connection() reports it as connecting until it settles, and a new
    // attempt replaces one still waiting. connect_host saves the address only
    // once the printer has answered.
    virtual PrinterConnectionInfo connection(const std::string& name) { return {}; }
    virtual void prepare_connection(const std::string& name) {}
    virtual DiscoveryPort discovery_port() { return DiscoveryPort::Ours; }
    virtual void sign_in_to_bambu() {}
    // Downloads and loads Bambu's network plug-in behind Orca's own progress
    // dialog, as Orca's "Click here to install it" does. Returns once that
    // dialog closes, whether or not the plug-in is loaded then.
    virtual void install_network_plugin() {}
    virtual std::string connect_printer(const std::string& name, const std::string& device_id,
                                       const std::string& access_code) { return "Connection is unavailable."; }
    virtual std::string connect_host(const std::string& name, const std::string& host_type,
                                    const std::string& address, const std::string& api_key) { return "Connection is unavailable."; }
    // Abandons this printer's attempt if it is still waiting: whatever the
    // printer answers afterwards is dropped.
    virtual void cancel_connection(const std::string& name) {}
};

} // namespace Slic3r::GUI::JusPrin::PrinterSetup

#endif
}

void OrcaPrinterBackend::sign_in_to_bambu()
{
    wxGetApp().request_login(false, BBL_CLOUD_PROVIDER);
}

void OrcaPrinterBackend::install_network_plugin()
{
    // Orca's own installer, as its "Click here to install it" hint runs it:
    // the download turns the plug-in's preference on and loads it in place.
    wxGetApp().ShowDownNetPluginDlg();
}

PrinterConnectionInfo OrcaPrinterBackend::connection(const std::string& name)
{
    PrinterConnectionInfo info;
    const auto saved = saved_printers();
    const auto printer = std::find_if(saved.begin(), saved.end(), [&](const SavedPrinter& p) { return p.name == name; });
    if (printer == saved.end()) {
        info.state = "unavailable";
        info.message = "This printer was renamed or removed. Open it again from Printers.";
        return info;
    }
    const CatalogPrinter* model = model_of(name);
    if (!model || model->vendor_id != "BBL") {
        const Preset* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
        if (!preset)
            throw std::logic_error("A saved printer has no preset");
        if (m_host_attempt && m_host_attempt->name == name && m_host_attempt->state == "connecting")
            settle(*m_host_attempt);
        const auto type = preset->config.opt_enum<PrintHostType>("host_type");
        info.address = preset->config.opt_string("print_host");
        info.host_type = type == htMoonraker ? "moonraker" : type == htOctoPrint ? "octoprint" : "other";
        info.provider = "host";
        info.state = info.address.empty() ? "not_configured" : "unknown";
        if (info.state == "unknown")
            info.message = "A connection is saved. Test it to check access; live printer status is not available here.";
        if (info.host_type == "other") {
            info.state = "unavailable";
            info.message = "Configure this connection type in Printer settings. You can still prepare prints and export a file.";
        }
        if (m_host_attempt && m_host_attempt->name == name) {
            auto& attempt = *m_host_attempt;
            // Only a verified attempt saved its settings; it holds while the
            // printer is still set up as it was tested.
            if (attempt.state == "verified" &&
                (info.address != attempt.address || info.host_type != attempt.host_type ||
                 preset->config.opt_string("printhost_apikey") != attempt.api_key)) {
                info.message = "Connection settings changed. Test the new connection again.";
                return info;
            }
            info.state = attempt.state;
            info.message = attempt.message;
        }
        return info;
    }
    info.provider = "bambu";
    info.device_id = printer->device_id;
    auto* devices = wxGetApp().getDeviceManager();
    auto* agent = wxGetApp().getAgent();
    info.signed_in = agent && agent->is_user_login(BBL_CLOUD_PROVIDER);
    if (fake_bambu_printer_agent_id(wxGetApp().app_config).empty() && !NetworkAgent::is_network_module_loaded()) {
        info.state = "unavailable";
        info.needs_network_plugin = true;
        info.message = "Connecting a Bambu Lab printer needs Bambu's network plug-in, which is not installed or not turned on. "
                       "The printer can already prepare prints without it.";
        return info;
    }
    if (!devices || !agent) {
        info.state = "unavailable";
        info.message = "Connecting is not available right now. The printer can already prepare prints.";
        return info;
    }
    // The local list is what has announced itself on this network; the cloud
    // list is the person's account, wherever those printers are.
    const auto nearby = devices->get_local_machinelist();
    auto candidates = nearby;
    for (const auto& entry : devices->get_my_cloud_machine_list())
        candidates[entry.first] = entry.second;
    for (const auto& [id, machine] : candidates) {
        if (!machine || machine->printer_type != model->device_model_id)
            continue;
        if (!info.device_id.empty() && id != info.device_id)
            continue;
        const bool used_elsewhere = std::any_of(saved.begin(), saved.end(), [&](const SavedPrinter& p) {
            return p.name != name && p.device_id == id;
        });
        if (!used_elsewhere && (!machine->is_lan_mode_printer() || machine->is_avaliable()))
            info.candidates.push_back({id, machine->get_dev_name(), machine->get_dev_ip(), machine->is_lan_mode_printer(),
                                       nearby.find(id) == nearby.end()});
    }
    MachineObject* machine = info.device_id.empty() ? nullptr : devices->get_my_machine(info.device_id);
    // is_connected() alone is optimistic immediately after reset(). Require
    // actual parsed push data, and fresh LAN data for a LAN connection.
    const bool communicating = machine && has_recent_printer_data(*machine);
    const bool configured = has_verified_printer_connection(info.device_id);
    info.state = communicating ? "verified" : configured ? "unknown" : "not_configured";
    if (info.state == "unknown")
        info.message = "Connection status is unknown. Check that the printer is on, then reconnect.";
    if (m_connection_attempt && m_connection_attempt->name == name) {
        const auto& attempt = *m_connection_attempt;
        if (info.device_id != attempt.device_id)
            throw std::logic_error("A connection attempt lost its saved printer association");
        const bool observed = communicating &&
            (machine->is_lan_mode_printer() ? machine->last_lan_msg_time_ > attempt.observation_start
                                           : machine->last_cloud_msg_time_ > attempt.observation_start);
        if (devices->get_selected_machine() != machine && machine != nullptr && !attempt.reselecting) {
            info.state = "failed";
            info.message = "The selected printer changed. Select this printer again to reconnect.";
        } else if (observed) {
            info.state = "verified";
            m_connection_attempt.reset();
        } else if (machine == nullptr) {
            info.state = "failed";
            info.message = "The printer is no longer available. Refresh the printer list and try again.";
        } else if (std::chrono::steady_clock::now() - attempt.started > kConnectionWait) {
            info.state = "failed";
            info.message = "The printer did not respond. Check that it is on the network and try again.";
        } else {
            info.state = "connecting";
            info.message.clear();
        }
    }
    if (info.state == "verified")
        wxGetApp().app_config->set("jusprin_verified_connections", info.device_id, "true");
    if (communicating) {
        const auto* extruders = machine->GetExtderSystem();
        info.nozzle_mismatch = extruders && extruders->GetNozzleDiameter(0) > 0 &&
            std::abs(extruders->GetNozzleDiameter(0) - printer->nozzle) > 0.001;
    }
    return info;
}

std::string OrcaPrinterBackend::connect_printer(const std::string& name, const std::string& device_id,
                                               const std::string& access_code)
{
    // The same printer asked for again keeps waiting; anything else replaces
    // the attempt below.
    if (m_connection_attempt && m_connection_attempt->name == name && m_connection_attempt->device_id == device_id &&
        connection(name).state == "connecting")
        return {};
    const auto info = connection(name);
    if (info.provider != "bambu" || info.state == "unavailable")
        return info.message;
    if (std::none_of(info.candidates.begin(), info.candidates.end(), [&](const ConnectionCandidate& p) { return p.id == device_id; }))
        return "Choose a matching printer from the refreshed list.";
    auto* devices = wxGetApp().getDeviceManager();
    MachineObject* machine = devices->get_my_machine(device_id);
    if (!machine)
        machine = devices->get_local_machine(device_id);
    if (!machine)
        return "That printer is no longer available. Refresh the list and try again.";
    if (machine->is_lan_mode_printer()) {
        if (access_code.empty() && !machine->has_access_right())
            return "Enter the access code shown on your printer.";
        if (!std::all_of(access_code.begin(), access_code.end(), [](unsigned char c) {
                return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
            }))
            return "The access code can only contain letters and numbers.";
    }
    const wxString problem = Printers::link_named_printer(name, device_id);
    if (!problem.empty())
        return problem.ToStdString();
    prepare_connection(name);
    if (machine->is_lan_mode_printer() && !access_code.empty())
        machine->set_user_access_code(access_code);
    m_connection_attempt = ConnectionAttempt{name, device_id, std::chrono::steady_clock::now(),
                                              std::chrono::system_clock::now()};
    if (devices->get_selected_machine() != machine) {
        devices->set_selected_machine(device_id);
        return {};
    }
    // Selecting the selected LAN printer again disconnects and reconnects
    // it, and GUI_App's local-connect handler hears the disconnect one event
    // turn later and clears the selection -- after the reconnect. Deselect
    // now, and select it again once that notice has run.
    m_connection_attempt->reselecting = true;
    devices->set_selected_machine("");
    wxGetApp().CallAfter([alive = std::weak_ptr<bool>(m_alive), this, device_id] {
        if (alive.expired() || !m_connection_attempt || m_connection_attempt->device_id != device_id)
            return;
        m_connection_attempt->reselecting = false;
        wxGetApp().getDeviceManager()->set_selected_machine(device_id);
    });
    return {};
}

std::string OrcaPrinterBackend::connect_host(const std::string& name, const std::string& host_type,
                                            const std::string& address, const std::string& api_key)
{
    const auto info = connection(name);
    if (info.provider != "host" || info.state == "unavailable")
        return info.message;
    if (host_type != "moonraker" && host_type != "octoprint")
        return "Choose Moonraker or OctoPrint.";
    if (address.empty() || address.find_first_of("\r\n\t @") != std::string::npos)
        return "Enter the printer's host name, IP address or HTTP URL without credentials.";
    if (address.find("://") != std::string::npos && address.rfind("http://", 0) != 0 && address.rfind("https://", 0) != 0)
        return "Use an HTTP or HTTPS address.";
    const auto* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
    if (!preset)
        return "This printer was renamed or removed.";
    // Reuse a saved secret only for the same endpoint and provider.
    const std::string key = api_key.empty() && address == info.address && host_type == info.host_type ?
        preset->config.opt_string("printhost_apikey") : api_key;
    // Tested on a copy: the printer's own settings change only once the host
    // has answered (settle).
    DynamicPrintConfig config = preset->config;
    config.set_key_value("host_type", new ConfigOptionEnum<PrintHostType>(host_type == "moonraker" ? htMoonraker : htOctoPrint));
    config.set_key_value("print_host", new ConfigOptionString(address));
    config.set_key_value("printhost_apikey", new ConfigOptionString(key));
    std::unique_ptr<PrintHost> host(PrintHost::get_print_host(&config));
    if (!host)
        throw std::logic_error("A supported print host has no adapter");
    // PrintHost::test blocks until the host answers, and a host that accepts
    // the connection and never replies holds it with no upper bound (Http's
    // DEFAULT_TIMEOUT_MAX is 0). So it runs on a thread of its own, as
    // upstream's upload queue runs these adapters. Nothing waits for it:
    // joining could hold the panel's close for as long as the host dawdles,
    // and kConnectionWait reports the failure meanwhile. The adapter keeps
    // copies of what it read from `config`.
    auto verdict = std::make_shared<std::atomic<HostVerdict>>(HostVerdict::Testing);
    std::thread([host = std::move(host), verdict] {
        wxString detail;
        verdict->store(host->test(detail) ? HostVerdict::Passed : HostVerdict::Failed);
    }).detach();
    m_host_attempt = HostAttempt{name, host_type, address, key, std::chrono::steady_clock::now(), std::move(verdict), "connecting", {}};
    return {};
}

void OrcaPrinterBackend::settle(HostAttempt& attempt)
{
    switch (attempt.verdict->load()) {
    case HostVerdict::Passed: {
        const wxString problem = Printers::configure_named_printer_host(
            attempt.name, attempt.host_type == "moonraker" ? htMoonraker : htOctoPrint, attempt.address, attempt.api_key);
        attempt.state   = problem.empty() ? "verified" : "failed";
        attempt.message = problem.ToStdString();
        // The test's answer is Home's first word on this host.
        if (problem.empty())
            Printers::note_host_answered(attempt.name);
        break;
    }
    case HostVerdict::Failed:
        attempt.state   = "failed";
        attempt.message = "Could not reach the print host. Check its address, API key and network, then try again.";
        break;
    case HostVerdict::Testing:
        if (std::chrono::steady_clock::now() - attempt.started > kConnectionWait) {
            attempt.state   = "failed";
            attempt.message = "The printer did not respond. Check that it is on the network and try again.";
        }
        break;
    }
}

void OrcaPrinterBackend::cancel_connection(const std::string& name)
{
    if (m_host_attempt && m_host_attempt->name == name && m_host_attempt->state == "connecting")
        m_host_attempt.reset();
    // A Bambu Lab printer stays linked to the device and selected, as after a
    // failure; undoing both is separate work.
    if (m_connection_attempt && m_connection_attempt->name == name)
        m_connection_attempt.reset();
}

void OrcaPrinterBackend::open_printer_settings(const std::string& name)
{
    // A stock profile is in a conversation only as the project's selected
    // printer, so its settings are the printer tab as it stands.
    if (!stock_printer(name).name.empty() && wxGetApp().preset_bundle->printers.get_selected_preset_name() == name) {
        SetupCommands::open_settings_tab(Preset::TYPE_PRINTER);
        return;
    }
    Printers::open_named_printer_settings(m_plater, name);
}

