{
    std::vector<std::string> words;
    std::size_t start = 0;
    for (std::size_t end; (end = key.find('_', start)) != std::string::npos; start = end + 1)
        words.push_back(key.substr(start, end - start));
    words.push_back(key.substr(start));
    return words;
