'''// The words or keys of a query, lower-cased, split on spaces, commas and
// semicolons.
inline std::vector<std::string> search_terms(const std::string& query)
{
    std::vector<std::string> terms;
    const std::string text = ascii_lower(query);
    for (std::size_t start = 0; start <= text.size();) {
        const std::size_t end = std::min(text.find_first_of(" ,;", start), text.size());
        if (end > start)
            terms.push_back(text.substr(start, end - start));
        start = end + 1;
    }
    return terms;
}

// When a search in `scope` matched nothing, the query's exact keys that are
// settings of another scope, so the empty page says why: the scope filter
// dropped them, not the dictionary. `definitions_of(scope)` gives a scope's
// definitions, the adapter's or a fake's.
template <class DefinitionsOf>
inline void note_other_scopes(SettingsSearchResult& result, const SettingsQuery& query, SettingsScope scope, DefinitionsOf definitions_of)
{
    if (!result.items.empty() || result.error)
        return;
    const std::vector<std::string> terms = search_terms(query.text);
    for (SettingsScope other : {SettingsScope::Process, SettingsScope::Filament, SettingsScope::Printer, SettingsScope::Object}) {
        if (other == scope)
            continue;
        for (const SettingDefinition& def : definitions_of(other)) {
            const std::string key = ascii_lower(def.key);
            const bool named = std::find(terms.begin(), terms.end(), key) != terms.end();
            const bool noted = std::any_of(result.other_scopes.begin(), result.other_scopes.end(),
                                           [&def](const auto& entry) { return entry.first == def.key; });
            if (named && !noted)
                result.other_scopes.emplace_back(def.key, other);
        }
    }
}

// `changed` lists the keys whose value differs from the saved preset; only
// read when the query asks for changed settings.
inline SettingsSearchResult search_setting_definitions('''
)])

