        listed.push_back(found.stable_id);
    for (PrinterSetup::DiscoveredPrinter& heard : PrinterSetup::discover_nearby_printers())
        if (std::find(listed.begin(), listed.end(), heard.stable_id) == listed.end())
            found_all.push_back(std::move(heard));
    for (const PrinterSetup::DiscoveredPrinter& found : found_all) {
        PrinterDevice device;
